exercises.solutionCode:
import { useState } from "react";

function ClickCounter({ initialCount }) {
  const [count, setCount] = useState(initialCount);

  function handleClick() {
    setCount(count + 1);
  }

  return <button onClick={handleClick}>Count: {count}</button>;
}

